<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Student Grades</title>
    <style>
        table {
            border-collapse: collapse;
            width: 100%;
        }
        th, td {
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }
        th {
            cursor: pointer;
        }
        #filterInput {
            padding: 6px;
            width: 100px;
        }
    </style>
</head>
<body>
    <h2>Student Grades</h2>
    <label for="subject">Select Subject:</label>
    <select id="subject">
        <option value="math">Math</option>
        <option value="science">Science</option>
        <option value="history">History</option>
    </select>
    <button onclick="fetchGrades()">Fetch Grades</button>
    <br><br>
    <input type="number" id="filterInput" placeholder="Filter by score">
    <button onclick="applyFilter()">Apply Filter</button>
    <br><br>
    <table id="gradesTable">
        <thead>
            <tr>
                <th onclick="sortTable('name')">Name</th>
                <th onclick="sortTable('score')">Score</th>
            </tr>
        </thead>
        <tbody id="tableBody">
        </tbody>
    </table>

    <script>
        function fetchGrades() {
            const subject = document.getElementById('subject').value;
            fetch(`/get_grades?subject=${subject}`)
                .then(response => response.json())
                .then(data => {
                    displayGrades(data);
                })
                .catch(error => {
                    console.error('Error fetching grades:', error);
                });
        }

        function displayGrades(data) {
            const tableBody = document.getElementById('tableBody');
            tableBody.innerHTML = '';
            data.forEach(student => {
                const row = document.createElement('tr');
                row.innerHTML = `<td>${student.name}</td><td>${student.score}</td>`;
                tableBody.appendChild(row);
            });
        }

        function sortTable(column) {
            const tableBody = document.getElementById('tableBody');
            const rows = Array.from(tableBody.rows);
            let sortedRows = [...rows];
            sortedRows.sort((a, b) => {
                const aVal = a.cells[column].textContent;
                const bVal = b.cells[column].textContent;
                return aVal.localeCompare(bVal);
            });
            tableBody.innerHTML = '';
            sortedRows.forEach(row => tableBody.appendChild(row));
        }

        function applyFilter() {
            const filterValue = parseFloat(document.getElementById('filterInput').value);
            const tableBody = document.getElementById('tableBody');
            const rows = Array.from(tableBody.rows);
            tableBody.innerHTML = '';
            rows.forEach(row => {
                const score = parseFloat(row.cells[1].textContent);
                if (isNaN(filterValue) || score > filterValue) {
                    tableBody.appendChild(row);
                }
            });
        }
    </script>
</body>
</html>
```

